// Dock density index — record JAH-GPC-TBDOCK-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"ports": 11, "max_res_mp": 16.6, "price_usd": 300};
var value = (m.ports*m.max_res_mp/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-TBDOCK-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-TBDOCK-000001|' + value.toFixed(2) + ' density index');

